module benchmark/solution

import std/string (repeat, chars)

pure func digitRoman(d: int, one: string, five: string, ten: string) -> string {
  if d == 9 then "${one}${ten}"
  else if d >= 5 then "${five}${repeat(one, d - 5)}"
  else if d == 4 then "${one}${five}"
  else repeat(one, d)
}

export pure func toRoman(n: int) -> string ! {}
requires { n >= 1, n <= 3999 }
{
  "${repeat("M", n / 1000)}${digitRoman((n / 100) % 10, "C", "D", "M")}${digitRoman((n / 10) % 10, "X", "L", "C")}${digitRoman(n % 10, "I", "V", "X")}"
}

pure func romanValue(c: string) -> int {
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0
  }
}

pure func decodeRoman(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => match rest {
      [] => romanValue(c),
      next :: _ =>
        if romanValue(c) < romanValue(next)
        then decodeRoman(rest) - romanValue(c)
        else romanValue(c) + decodeRoman(rest)
    }
  }

export pure func fromRoman(s: string) -> int = decodeRoman(chars(s))

export pure func roundtrip(n: int) -> bool ! {}
requires { n >= 1, n <= 3999 }
ensures { result }
{
  fromRoman(toRoman(n)) == n
}

export pure func distinctEncoding(a: int, b: int) -> bool ! {}
requires { a >= 1, a <= 3999, b >= 1, b <= 3999, a != b }
ensures { result }
{
  toRoman(a) != toRoman(b)
}

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

